import type { Resource } from "@dylanebert/shallot";
import {
    lit,
    MaterialPlugin,
    type MaterialHandle,
    materialType,
} from "@dylanebert/shallot/standard/rendering";
import * as d from "typegpu/data";
import * as std from "typegpu/std";

/** Stripes per unit along the cube's diagonal. */
export const STRIPE_FREQUENCY = 3;
/** Stripe periods travelled per second. */
export const STRIPE_SPEED = 0.6;

export const StripeParameters = d.struct({
    time: d.f32,
    darkColor: d.vec3f,
    lightColor: d.vec3f,
});

/**
 * Diagonal bands in object space, so they wrap continuously across every face,
 * sliding along the diagonal as `time` advances.
 */
export const StripeMaterial = materialType({
    name: "MovingStripes",
    parameters: StripeParameters,
    defaults: { time: 0, darkColor: d.vec3f(0), lightColor: d.vec3f(1) },
    fragmentInputs: { localPos: true },
    fragment: (ctx) => {
        "use gpu";
        const p = ctx.localPos;
        const phase = (p.x + p.y + p.z) * STRIPE_FREQUENCY - ctx.parameters.time * STRIPE_SPEED;
        const band = std.step(0.5, std.fract(phase));
        const color = std.mix(ctx.parameters.darkColor, ctx.parameters.lightColor, band);
        return d.vec4f(lit(color, ctx.worldNormal), 1);
    },
});
export const StripePlugin = MaterialPlugin(StripeMaterial);

/** The stripe clock and the cube's stripe material. */
export const Stripes: Resource<{ time: number; handle?: MaterialHandle }> = {
    create: () => ({ time: 0 }),
};
