            {
                name: "StripeScene",
                dependencies: [StandardRenderingPlugin, MeshRenderPlugin, StripePlugin],
                initialize(world) {
                    camera = world.create();
                    world.add(camera, Transform, {
                        translation: [1.6, 1.3, 1.6],
                        rotation: lookAtRotation(1.6, 1.3, 1.6, 0, 0, 0),
                    });
                    world.add(camera, Camera, { antialias: 0 });
                    world.add(camera, StandardRenderer);
                    world.add(camera, Tonemapping, { method: TonemappingMethod.None });
                    attachTexture(world, camera, { width: SIZE, height: SIZE });
                    const sun = world.create();
                    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
                    world.add(sun, DirectionalLight, { illuminance: 3200 });
                    handle = world.resource(StripeMaterial).add({
                        time: 0,
                        darkColor: d.vec3f(0.02),
                        lightColor: d.vec3f(0.9, 0.5, 0.1),
                    });
                    const cube = world.create();
                    world.add(cube, Transform);
                    world.add(cube, MeshInstance);
                    world.add(cube, MeshMaterial, handle);
                },
            },
        ],
    });
    try {
        const { world } = app;
        const frame = async (time: number) => {
            world.resource(StripeMaterial).update(handle, { time });
            world.step(0);
            world.step(0);
            return (await captureTexture(world, camera)).rgba;
        };
        const before = await frame(0);
        // A quarter period later, a quarter of every band has moved under the camera.
        const after = await frame(0.25 / STRIPE_SPEED);

        let dark = 0;
        let light = 0;
        let changed = 0;
        for (let y = 20; y < 44; y++)
            for (let x = 20; x < 44; x++) {
                const i = (y * SIZE + x) * 4;
                if (before[i]! < 30) dark++;
                else if (before[i]! > 80) light++;
                if (Math.abs(before[i]! - after[i]!) > 30) changed++;
            }
        console.log({ dark, light, changed });
        expect(dark, "dark band pixels on the cube").toBeGreaterThan(50);
        expect(light, "light band pixels on the cube").toBeGreaterThan(50);
        expect(changed, "pixels the moving bands changed").toBeGreaterThan(50);
    } finally {
        app.dispose();
    }
});
